    private final Room deluxe = new Room(201, RoomType.DELUXE, 3, new BigDecimal("389.90"));

    private static LocalDate d(String date) {
        return LocalDate.parse(date);
    }

    private static ErrorCode errorOf(Runnable action) {
        return org.junit.jupiter.api.Assertions.assertThrows(HotelException.class, action::run).errorCode();
    }

    \@Test
    void corporateDiscountDependsOnTheCompany() {
        Price price = calculator.calculate(deluxe, d("2027-03-10"), d("2027-03-12"), RatePlan.CORPORATE, "TECNOSUL");

        assertEquals(new BigDecimal("779.80"), price.subtotal());
        assertEquals(new BigDecimal("93.58"), price.discount());
        assertEquals(new BigDecimal("686.22"), price.total());
    }

    \@Test
    void corporateNeedsAKnownCompany() {
        for (String code : new String[] {null, "", "tecnosul", "OUTRA"}) {
            assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> calculator.calculate(
                    deluxe, d("2027-03-10"), d("2027-03-12"), RatePlan.CORPORATE, code)));
        }
    }

    \@Test
    void weekendPackageIsAFixedPriceAllYear() {
        Price price = calculator.calculate(deluxe, d("2027-03-12"), d("2027-03-14"), RatePlan.WEEKEND_PACKAGE);
        assertEquals(new BigDecimal("820.00"), price.subtotal());
        assertEquals(new BigDecimal("0.00"), price.discount());
        assertEquals(new BigDecimal("820.00"), price.total());

        Price highSeason = calculator.calculate(suite, d("2027-01-08"), d("2027-01-10"), RatePlan.WEEKEND_PACKAGE);
        assertEquals(new BigDecimal("1200.00"), highSeason.total());
        assertEquals(2, highSeason.nights());
    }

    \@Test
    void weekendPackageOnlyFridayToSunday() {
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> calculator.calculate(
                deluxe, d("2027-03-11"), d("2027-03-13"), RatePlan.WEEKEND_PACKAGE)));
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> calculator.calculate(
                deluxe, d("2027-03-12"), d("2027-03-15"), RatePlan.WEEKEND_PACKAGE)));
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> calculator.calculate(
                deluxe, d("2027-03-12"), d("2027-03-13"), RatePlan.WEEKEND_PACKAGE)));
    }

    \@Test
    void longStayGivesTenPercentFromSevenNights() {
        Price price = calculator.calculate(standardRoom, d("2027-03-01"), d("2027-03-08"), RatePlan.LONG_STAY);

        assertEquals(new BigDecimal("1749.30"), price.subtotal());
        assertEquals(new BigDecimal("174.93"), price.discount());
        assertEquals(new BigDecimal("1574.37"), price.total());
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> calculator.calculate(
                standardRoom, d("2027-03-01"), d("2027-03-07"), RatePlan.LONG_STAY)));
    }
}
